sys_element_mapping.value:
HoC OHSM - Telework - Error when sending agreement {{subflow.telework_agreement.number}}to Unit 4: 
{
Error Code:{{90b75bc3-06d6-4a34-8c36-a06a636127ba.response_code}}
Error Message:{{90b75bc3-06d6-4a34-8c36-a06a636127ba.response_body}}
}

sys_hub_input_scripts.script:
{"record":{"scriptActive":false,"script":"/*
**Access Flow/Action data using the fd_data object. Script must return a value. 
**Order number is offset by +1 in Error Handling Section.
**Available options display upon pressing "." after fd_data
**example: var shortDesc = fd_data.trigger.current.short_description;
**return shortDesc;
*/

"}}

{"employeenumber":{"scriptActive":false,"script":"/*
**Access Flow/Action data using the fd_data object. Script must return a value. 
**Order number is offset by +1 in Error Handling Section.
**Available options display upon pressing "." after fd_data
**example: var shortDesc = fd_data.trigger.current.short_description;
**return shortDesc;
*/
const user = fd_data.subflow_inputs.input3;
const hrProfile = fd_data.subflow_inputs.input3_hr_profile;
const employeeNumber = hrProfile.u_employee_number_unit4 ||
 hrProfile.employee_number ||
 user.employee_number; //if u_employee_number_unit4 is empty try the other values (less accurate);

return employeeNumber;
"}}

{"teleworkagreement":{"scriptActive":false,"script":"/*
**Access Flow/Action data using the fd_data object. Script must return a value. 
**Order number is offset by +1 in Error Handling Section.
**Available options display upon pressing "." after fd_data
**example: var shortDesc = fd_data.trigger.current.short_description;
**return shortDesc;
*/
const util = new x_hccc_hoc_ohs.HoCOHSMTelWrkUtils();
const unit4Obj = util._getUnit4Obj(fd_data.subflow_inputs.input4);
const teleworkAgreementString = JSON.stringify(unit4Obj);

return teleworkAgreementString;"}}

{"employee_number":{"scriptActive":true,"script":"/*
**Access Flow/Action data using the fd_data object. Script must return a value. 
**Order number is offset by +1 in Error Handling Section.
**Available options display upon pressing "." after fd_data
**example: var shortDesc = fd_data.trigger.current.short_description;
**return shortDesc;
*/
const telWrkUtil = new x_hccc_hoc_ohs.HoCOHSMTelWrkUtils();
const user = fd_data.subflow_inputs.telework_agreement.subject_person;
const employeeNumber = telWrkUtil._getEmployeeNumber(user);
/*
const hrProfile = fd_data.subflow_inputs.telework_agreement.subject_person_hr_profile;
const employeeNumber = (hrProfile.u_employee_number_unit4 ||
 hrProfile.employee_number ||
 user.employee_number) + ''; //if u_employee_number_unit4 is empty try the other values (less accurate);
*/

return employeeNumber;
"}}

{"json_agreement":{"scriptActive":true,"script":"/*
**Access Flow/Action data using the fd_data object. Script must return a value. 
**Order number is offset by +1 in Error Handling Section.
**Available options display upon pressing "." after fd_data
**example: var shortDesc = fd_data.trigger.current.short_description;
**return shortDesc;
*/
const util = new x_hccc_hoc_ohs.HoCOHSMTelWrkUtils();
const unit4Obj = util._getUnit4Obj(fd_data.subflow_inputs.telework_agreement);
const teleworkAgreementString = JSON.stringify(unit4Obj);

return teleworkAgreementString;"}}

